<script setup>
import { ref,reactive,computed,shallowRef } from 'vue';
import AppDialog from './AppDialog.vue';import FormField from './FormField.vue';
import { state,dispatch,locate,notify } from '../state';
import { t,number } from '../i18n';
import { inventoryErrorText as errorText } from '../inventory-errors.mjs';
import { inventoryCategories } from '../inventory-categories.mjs';
import { STOCK_COUNT_LIMIT,stockCountScope,previewStockCount } from '../../core/stock-count.mjs';
const props=defineProps({materialIds:{type:Array,default:()=>[]},initialLocation:{type:String,default:''},initialCategory:{type:String,default:''}});
const emit=defineEmits(['close','saved']);const scope=reactive({category:props.initialCategory,locationId:props.initialLocation,materialId:''}),observations=reactive({}),reason=ref(''),page=ref(1),review=ref(null),payload=ref(null),captured=shallowRef(null),error=ref(''),busy=ref(false);let operationId;
const materials=computed(()=>state.value.materials.filter(row=>!row.archived&&(!props.materialIds.length||props.materialIds.includes(row.id))));
const lots=computed(()=>stockCountScope(state.value,{category:scope.category,locationId:scope.locationId,materialIds:scope.materialId?[scope.materialId]:props.materialIds}));
const observedLots=computed(()=>lots.value.filter(row=>String(observations[row.id]??'').trim()!==''));
const pageCount=computed(()=>Math.max(1,Math.ceil(lots.value.length/20)));const visible=computed(()=>lots.value.slice((Math.min(page.value,pageCount.value)-1)*20,Math.min(page.value,pageCount.value)*20));
const material=id=>state.value.materials.find(row=>row.id===id),lot=id=>state.value.lots.find(row=>row.id===id),project=id=>state.value.projects.find(row=>row.id===id);
const result=computed(()=>{if(!review.value)return {};try{return {preview:previewStockCount(captured.value,payload.value)};}catch(caught){return {error:errorText(caught)};}});
function reviewCount(){error.value='';try{if(!reason.value.trim())throw {code:'required'};const rows=observedLots.value.map(row=>({lotId:row.id,observed:observations[row.id]}));captured.value=state.value;payload.value={previewRevision:state.value.revision,reason:reason.value,rows};const first=previewStockCount(captured.value,payload.value);payload.value.rows=first.rows.map(row=>({lotId:row.lotId,observed:row.observed,decision:row.conflict||row.holdConflict?'':'keep',allocations:row.allocations.map(a=>({projectId:a.projectId,quantity:a.before}))}));review.value=first;operationId=crypto.randomUUID();}catch(caught){error.value=errorText(caught);}}
async function apply(){if(busy.value)return;busy.value=true;error.value='';try{await dispatch('stock.countBatch',payload.value,operationId);notify();emit('saved');}catch(caught){error.value=errorText(caught);if(caught.code==='inventory_preview_stale'||caught.code==='stale_revision')review.value=null;}finally{busy.value=false;}}
</script>
<template><AppDialog :title="t('stockCountTitle')" wide :busy="busy" @close="emit('close')"><p class="notice">{{ t('stockCountHelp') }}</p><p v-if="error||result.error" role="alert" class="notice error">{{ error||result.error }}</p>
<template v-if="!review"><div class="form-grid"><FormField :label="t('location')" v-slot="{id}"><select :id="id" v-model="scope.locationId" @change="page=1"><option value="">{{ t('all') }}</option><option v-for="row in state.locations" :key="row.id" :value="row.id">{{ locate(row.id) }}</option></select></FormField><FormField :label="t('category')" v-slot="{id}"><select :id="id" v-model="scope.category" @change="page=1"><option value="">{{ t('all') }}</option><option v-for="row in inventoryCategories" :key="row.value" :value="row.value">{{ row.label }}</option></select></FormField><FormField :label="t('materials')" wide v-slot="{id}"><select :id="id" v-model="scope.materialId" @change="page=1"><option value="">{{ t('all') }}</option><option v-for="row in materials" :key="row.id" :value="row.id">{{ row.name }} · {{ row.code }}</option></select></FormField><FormField :label="t('reason')" wide required v-slot="{id}"><textarea :id="id" v-model="reason" maxlength="2000"/></FormField></div><p v-if="observedLots.length>STOCK_COUNT_LIMIT" role="alert" class="notice warning">{{ t('count_batch_limit') }}</p><div class="table-wrap"><table><thead><tr><th>{{ t('materials') }} / {{ t('lot') }}</th><th>{{ t('countRegistered') }}</th><th>{{ t('countObserved') }}</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td>{{ material(row.materialId)?.name }}<small class="cell-subtitle">{{ row.lotCode||row.id.slice(0,8) }} · {{ locate(row.locationId) }}</small></td><td>{{ number(row.quantity,6) }} {{ t(`unit_${row.unit}`) }}</td><td><input v-model="observations[row.id]" inputmode="decimal" :aria-label="`${t('countObserved')}: ${material(row.materialId)?.name} / ${row.lotCode||row.id.slice(0,8)}`"/></td></tr></tbody></table></div><p v-if="!lots.length" class="field-help">{{ t('empty') }}</p><div v-if="pageCount>1" class="actions form-section"><button class="button small" :disabled="page<=1" @click="page--">{{ t('previousPage') }}</button><span>{{ Math.min(page,pageCount) }} / {{ pageCount }}</span><button class="button small" :disabled="page>=pageCount" @click="page++">{{ t('nextPage') }}</button></div></template>
<template v-else><section v-for="(row,index) in review.rows" :key="row.lotId" class="form-section"><h3>{{ material(row.materialId)?.name }} · {{ lot(row.lotId)?.lotCode||row.lotId.slice(0,8) }}</h3><div class="stat-row"><span>{{ t('countRegistered') }}</span><strong>{{ number(row.before,6) }} {{ t(`unit_${row.unit}`) }}</strong></div><div class="stat-row"><span>{{ t('countObserved') }}</span><strong>{{ number(row.observed,6) }} {{ t(`unit_${row.unit}`) }}</strong></div><div class="stat-row"><span>{{ t('countDifference') }}</span><strong>{{ number(row.difference,6) }} {{ t(`unit_${row.unit}`) }}</strong></div><p v-if="row.costUnknown" class="notice warning">{{ t('countCostUnknown') }}</p><p v-if="row.held" class="notice">{{ t('countToolHolds',{quantity:number(row.held,6),unit:t(`unit_${row.unit}`)}) }}</p><template v-if="row.conflict||row.holdConflict"><p class="notice error">{{ t('countConflict',{quantity:number(row.conflict+row.holdConflict,6),unit:t(`unit_${row.unit}`)}) }}</p><FormField :label="t('countDecision')" required v-slot="{id}"><select :id="id" v-model="payload.rows[index].decision"><option value="" disabled>{{ t('countChooseDecision') }}</option><option value="keep">{{ t('countKeep') }}</option><option value="allocate">{{ t('countAllocate') }}</option></select></FormField></template><div v-if="row.allocations.length" class="table-wrap"><table><thead><tr><th>{{ t('project') }}</th><th>{{ t('reserved') }}</th><th>{{ t('countAfter') }}</th></tr></thead><tbody><tr v-for="(allocation,position) in row.allocations" :key="allocation.projectId"><td>{{ project(allocation.projectId)?.name }}</td><td>{{ number(allocation.before,6) }}</td><td><input v-if="payload.rows[index].decision==='allocate'" v-model="payload.rows[index].allocations[position].quantity" inputmode="decimal" :aria-label="`${t('countAfter')}: ${project(allocation.projectId)?.name} / ${lot(row.lotId)?.lotCode||row.lotId}`"/><span v-else>{{ number(allocation.before,6) }}</span></td></tr></tbody></table></div><p v-if="payload.rows[index].decision==='keep'&&(row.conflict||row.holdConflict)" class="notice warning">{{ t('countKeepHelp') }}</p><p v-if="result.preview?.rows[index]?.problem" class="notice warning">{{ t(result.preview.rows[index].problem) }}</p></section><section v-if="review.requirements.length" class="form-section"><h3>{{ t('countRequirements') }}</h3><p class="notice">{{ t('countRequirementsHelp') }}</p><div v-for="need in review.requirements" :key="`${need.projectId}:${need.materialId}`" class="stat-row"><span>{{ project(need.projectId)?.name }} · {{ material(need.materialId)?.name }}</span><strong>{{ number(need.quantity,6) }} {{ t(`unit_${need.unit}`) }} · {{ t(need.create?'countNewNeed':'countExistingNeed') }}</strong></div></section></template>
<template #footer><button class="button" :disabled="busy" @click="emit('close')">{{ t('cancel') }}</button><button v-if="review" class="button" :disabled="busy" @click="review=null">{{ t('back') }}</button><button v-if="!review" class="button primary" :disabled="!observedLots.length||observedLots.length>STOCK_COUNT_LIMIT" @click="reviewCount">{{ t('previewChanges') }}</button><button v-else class="button primary" :disabled="busy||!result.preview?.ready" @click="apply">{{ t('countApply') }}</button></template></AppDialog></template>
